/// Persistent UI state for the modeless Native 2D authoring workspace.

new:
    fn cancel_gesture(&mut self) -> Result<(), String> {
        if self.gesture_active {
            self.service.cancel_gesture().map_err(|error| error.to_string())?;
        }
        self.gesture_active = false;
        self.gesture_start = None;
        Ok(())
    }

    fn mcp_inspect(
        &self,
        permissions: &AuthoringPermissions,
    ) -> Result<Value, Native2dMcpCallFailure> {
        mcp_value(
            TypedDocumentAuthoringService::new()
                .inspect(self.service.document(), &self.state, permissions)
                .map_err(Native2dMcpCallFailure::typed)?,
        )
    }

    fn mcp_validate(
        &self,
        permissions: &AuthoringPermissions,
    ) -> Result<Value, Native2dMcpCallFailure> {
        mcp_value(
            TypedDocumentAuthoringService::new()
                .validate(self.service.document(), &self.state, permissions)
                .map_err(Native2dMcpCallFailure::typed)?,
        )
    }

    fn mcp_preview(
        &self,
        permissions: &AuthoringPermissions,
        input: TypedDocumentMutationInput<engine_authoring::TileMapDocument>,
    ) -> Result<Value, Native2dMcpCallFailure> {
        mcp_value(
            TypedDocumentAuthoringService::new()
                .preview(
                    self.service.document(),
                    &self.state,
                    permissions,
                    input.expected_revision,
                    input.expected_generation,
                    input.replacement,
                )
                .map_err(Native2dMcpCallFailure::typed)?,
        )
    }

    fn mcp_apply(
        &mut self,
        project: &ProjectRoot,
        manifest: &engine::AssetManifest,
        permissions: &AuthoringPermissions,
        input: TypedDocumentMutationInput<engine_authoring::TileMapDocument>,
    ) -> Result<Value, Native2dMcpCallFailure> {
        if self.gesture_active {
            return Err(Native2dMcpCallFailure::new(
                "editor.native_2d_gesture_active",
                "finish or cancel the active Tile Map gesture before an MCP replacement",
            ));
        }
        let mut next_document = self.service.document().clone();
        let mut next_state = self.state;
        let mutation = TypedDocumentAuthoringService::new()
            .apply(
                &mut next_document,
                &mut next_state,
                permissions,
                input.expected_revision,
                input.expected_generation,
                input.replacement,
            )
            .map_err(Native2dMcpCallFailure::typed)?;
        if mutation.success && !mutation.diff.is_empty() {
            let next_tiles = load_tile_set_for_map(project, manifest, &next_document).map_err(
                |message| {
                    Native2dMcpCallFailure::new(
                        "editor.native_2d_dependency_unresolved",
                        message,
                    )
                },
            )?;
            let mut next_service = self.service.clone();
            next_service
                .replace_document(next_document.clone())
                .map_err(|error| {
                    Native2dMcpCallFailure::new(
                        "editor.native_2d_replace_failed",
                        error.to_string(),
                    )
                })?;
            let json = next_document.canonical_json().map_err(|error| {
                Native2dMcpCallFailure::new(
                    "editor.native_2d_persist_failed",
                    error.to_string(),
                )
            })?;
            replace_file_contents(&self.path, &json).map_err(|error| {
                Native2dMcpCallFailure::new(
                    "editor.native_2d_persist_failed",
                    error.to_string(),
                )
            })?;
            self.service = next_service;
            self.state = next_state;
            self.tiles = next_tiles;
            self.selected_layer = self
                .selected_layer
                .min(self.service.document().layers.len().saturating_sub(1));
            self.selected_tile = self.tiles.tiles.first().map(|tile| tile.id.clone());
            self.dirty = false;
            self.affected_chunks.clear();
        }
        mcp_value(mutation)
    }
}

